		/** 
		 * Tests creating a new Role.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Role");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Role" );

			try {            
				Role entity = RoleService.getRoleInstance().createRole( generateNewEntity() );
				thePrimaryKey = entity.getRoleId();
				LOGGER.info( "-- Successfully created a Role with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Role. 
		 */
		public Role testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Role" );

			Role entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Role with primary key" );
			msg.append( thePrimaryKey );
			
			RoleFetchOneSummary fetchOneSummary = new RoleFetchOneSummary( thePrimaryKey );

			try {
				entity = RoleService.getRoleInstance().getRole( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Role " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Role.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Role." );

			StringBuilder msg = new StringBuilder( "Failed to update a Role : " );        
			Role entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Role." );

				// for use later on...
				thePrimaryKey = entity.getRoleId();

				RoleService proxy = RoleService.getRoleInstance();            
				proxy.updateRole( entity );   

				LOGGER.info( "-- Successfully saved Role - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Role.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Role." );

			try{
			    Role entity = testRead(); 
				RoleService.getRoleInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Role with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Role with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Roles.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Roles:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Role : " );        
			List<Role> collection  = null;

			try {
				// call the static get method on the RoleService
				collection = RoleService.getRoleInstance().getAllRole();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Role entity = null;            
					Iterator<Role> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getRoleId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

